module max_onions_protected (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] onion0_x, onion0_y,\n    input wire [7:0] onion1_x, onion1_y,\n    input wire [7:0] onion2_x, onion2_y,\n    input wire [7:0] onion3_x, onion3_y,\n    input wire [7:0] onion4_x, onion4_y,\n    input wire [7:0] fence0_x, fence0_y,\n    input wire [7:0] fence1_x, fence1_y,\n    input wire [7:0] fence2_x, fence2_y,\n    input wire [7:0] fence3_x, fence3_y,\n    input wire [7:0] fence4_x, fence4_y,\n    output reg [2:0] max_onions,\n    output reg done\n);\n    localparam N = 5;\n    localparam M = 5;\n    localparam IDX_WIDTH = 3;\n\n    // State definitions\n    localparam [4:0] IDLE = 5'd0;\n    localparam [4:0] LOAD_INPUTS = 5'd1;\n    localparam [4:0] INIT = 5'd2;\n    localparam [4:0] GET_FENCE_VERTICES = 5'd3;\n    localparam [4:0] LOAD_COORDINATES = 5'd4;\n    localparam [4:0] INIT_ONION_LOOP = 5'd5;\n    localparam [4:0] COMPUTE_AB = 5'd6;\n    localparam [4:0] COMPUTE_AP = 5'd7;\n    localparam [4:0] COMPUTE_CROSS1 = 5'd8;\n    localparam [4:0] COMPUTE_BC = 5'd9;\n    localparam [4:0] COMPUTE_BP = 5'd10;\n    localparam [4:0] COMPUTE_CROSS2 = 5'd11;\n    localparam [4:0] COMPUTE_CA = 5'd12;\n    localparam [4:0] COMPUTE_CP = 5'd13;\n    localparam [4:0] COMPUTE_CROSS3 = 5'd14;\n    localparam [4:0] CHECK_INSIDE = 5'd15;\n    localparam [4:0] UPDATE_COUNT = 5'd16;\n    localparam [4:0] NEXT_ONION = 5'd17;\n    localparam [4:0] UPDATE_MAX = 5'd18;\n    localparam [4:0] NEXT_S = 5'd19;\n    localparam [4:0] DONE = 5'd20;\n\n    // Input storage\n    reg [7:0] onion_x_reg [0:N-1];\n    reg [7:0] onion_y_reg [0:N-1];\n    reg [7:0] fence_x_reg [0:M-1];\n    reg [7:0] fence_y_reg [0:M-1];\n\n    // State and counters\n    reg [4:0] state;\n    reg [2:0] s;\n    reg [2:0] onion_idx;\n    reg [2:0] inside_count;\n    reg [2:0] max_onions_reg;\n\n    // Triangle coordinates\n    reg [7:0] A_x, A_y, B_x, B_y, C_x, C_y;\n\n    // Intermediate calculations\n    reg signed [15:0] AB_x, AB_y;\n    reg signed [15:0] AP_x, AP_y;\n    reg signed [15:0] BC_x, BC_y;\n    reg signed [15:0] BP_x, BP_y;\n    reg signed [15:0] CA_x, CA_y;\n    reg signed [15:0] CP_x, CP_y;\n    reg signed [31:0] cross1, cross2, cross3;\n    reg inside_flag;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            max_onions <= 3'd0;\n            max_onions_reg <= 3'd0;\n            s <= 3'd0;\n            onion_idx <= 3'd0;\n            inside_count <= 3'd0;\n            A_x <= 8'd0; A_y <= 8'd0;\n            B_x <= 8'd0; B_y <= 8'd0;\n            C_x <= 8'd0; C_y <= 8'd0;\n            AB_x <= 16'd0; AB_y <= 16'd0;\n            AP_x <= 16'd0; AP_y <= 16'd0;\n            BC_x <= 16'd0; BC_y <= 16'd0;\n            BP_x <= 16'd0; BP_y <= 16'd0;\n            CA_x <= 16'd0; CA_y <= 16'd0;\n            CP_x <= 16'd0; CP_y <= 16'd0;\n            cross1 <= 32'd0; cross2 <= 32'd0; cross3 <= 32'd0;\n            inside_flag <= 1'b0;\n            // Initialize arrays\n            onion_x_reg[0] <= 8'd0; onion_y_reg[0] <= 8'd0;\n            onion_x_reg[1] <= 8'd0; onion_y_reg[1] <= 8'd0;\n            onion_x_reg[2] <= 8'd0; onion_y_reg[2] <= 8'd0;\n            onion_x_reg[3] <= 8'd0; onion_y_reg[3] <= 8'd0;\n            onion_x_reg[4] <= 8'd0; onion_y_reg[4] <= 8'd0;\n            fence_x_reg[0] <= 8'd0; fence_y_reg[0] <= 8'd0;\n            fence_x_reg[1] <= 8'd0; fence_y_reg[1] <= 8'd0;\n            fence_x_reg[2] <= 8'd0; fence_y_reg[2] <= 8'd0;\n            fence_x_reg[3] <= 8'd0; fence_y_reg[3] <= 8'd0;\n            fence_x_reg[4] <= 8'd0; fence_y_reg[4] <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= LOAD_INPUTS;\n                end\n\n                LOAD_INPUTS: begin\n                    onion_x_reg[0] <= onion0_x; onion_y_reg[0] <= onion0_y;\n                    onion_x_reg[1] <= onion1_x; onion_y_reg[1] <= onion1_y;\n                    onion_x_reg[2] <= onion2_x; onion_y_reg[2] <= onion2_y;\n                    onion_x_reg[3] <= onion3_x; onion_y_reg[3] <= onion3_y;\n                    onion_x_reg[4] <= onion4_x; onion_y_reg[4] <= onion4_y;\n                    fence_x_reg[0] <= fence0_x; fence_y_reg[0] <= fence0_y;\n                    fence_x_reg[1] <= fence1_x; fence_y_reg[1] <= fence1_y;\n                    fence_x_reg[2] <= fence2_x; fence_y_reg[2] <= fence2_y;\n                    fence_x_reg[3] <= fence3_x; fence_y_reg[3] <= fence3_y;\n                    fence_x_reg[4] <= fence4_x; fence_y_reg[4] <= fence4_y;\n                    state <= INIT;\n                end\n\n                INIT: begin\n                    s <= 3'd0;\n                    max_onions_reg <= 3'd0;\n                    state <= GET_FENCE_VERTICES;\n                end\n\n                GET_FENCE_VERTICES: begin\n                    A_x <= fence_x_reg[s];\n                    A_y <= fence_y_reg[s];\n                    // Determine B and C indices (s+1 mod 5, s+2 mod 5)\n                    case (s)\n                        3'd0: begin B_x <= fence_x_reg[1]; B_y <= fence_y_reg[1]; C_x <= fence_x_reg[2]; C_y <= fence_y_reg[2]; end\n                        3'd1: begin B_x <= fence_x_reg[2]; B_y <= fence_y_reg[2]; C_x <= fence_x_reg[3]; C_y <= fence_y_reg[3]; end\n                        3'd2: begin B_x <= fence_x_reg[3]; B_y <= fence_y_reg[3]; C_x <= fence_x_reg[4]; C_y <= fence_y_reg[4]; end\n                        3'd3: begin B_x <= fence_x_reg[4]; B_y <= fence_y_reg[4]; C_x <= fence_x_reg[0]; C_y <= fence_y_reg[0]; end\n                        3'd4: begin B_x <= fence_x_reg[0]; B_y <= fence_y_reg[0]; C_x <= fence_x_reg[1]; C_y <= fence_y_reg[1]; end\n                    endcase\n                    state <= INIT_ONION_LOOP;\n                end\n\n                INIT_ONION_LOOP: begin\n                    onion_idx <= 3'd0;\n                    inside_count <= 3'd0;\n                    state <= COMPUTE_AB;\n                end\n\n                COMPUTE_AB: begin\n                    AB_x <= $signed(B_x) - $signed(A_x);\n                    AB_y <= $signed(B_y) - $signed(A_y);\n                    state <= COMPUTE_AP;\n                end\n\n                COMPUTE_AP: begin\n                    AP_x <= $signed(onion_x_reg[onion_idx]) - $signed(A_x);\n                    AP_y <= $signed(onion_y_reg[onion_idx]) - $signed(A_y);\n                    state <= COMPUTE_CROSS1;\n                end\n\n                COMPUTE_CROSS1: begin\n                    cross1 <= AB_x * AP_y - AB_y * AP_x;\n                    state <= COMPUTE_BC;\n                end\n\n                COMPUTE_BC: begin\n                    BC_x <= $signed(C_x) - $signed(B_x);\n                    BC_y <= $signed(C_y) - $signed(B_y);\n                    state <= COMPUTE_BP;\n                end\n\n                COMPUTE_BP: begin\n                    BP_x <= $signed(onion_x_reg[onion_idx]) - $signed(B_x);\n                    BP_y <= $signed(onion_y_reg[onion_idx]) - $signed(B_y);\n                    state <= COMPUTE_CROSS2;\n                end\n\n                COMPUTE_CROSS2: begin\n                    cross2 <= BC_x * BP_y - BC_y * BP_x;\n                    state <= COMPUTE_CA;\n                end\n\n                COMPUTE_CA: begin\n                    CA_x <= $signed(A_x) - $signed(C_x);\n                    CA_y <= $signed(A_y) - $signed(C_y);\n                    state <= COMPUTE_CP;\n                end\n\n                COMPUTE_CP: begin\n                    CP_x <= $signed(onion_x_reg[onion_idx]) - $signed(C_x);\n                    CP_y <= $signed(onion_y_reg[onion_idx]) - $signed(C_y);\n                    state <= COMPUTE_CROSS3;\n                end\n\n                COMPUTE_CROSS3: begin\n                    cross3 <= CA_x * CP_y - CA_y * CP_x;\n                    state <= CHECK_INSIDE;\n                end\n\n                CHECK_INSIDE: begin\n                    inside_flag <= ((cross1 < 32'sd0) && (cross2 < 32'sd0) && (cross3 < 32'sd0));\n                    state <= UPDATE_COUNT;\n                end\n\n                UPDATE_COUNT: begin\n                    if (inside_flag) inside_count <= inside_count + 3'd1;\n                    state <= NEXT_ONION;\n                end\n\n                NEXT_ONION: begin\n                    if (onion_idx < 3'd4) begin\n                        onion_idx <= onion_idx + 3'd1;\n                        state <= COMPUTE_AB;\n                    end else begin\n                        state <= UPDATE_MAX;\n                    end\n                end\n\n                UPDATE_MAX: begin\n                    if (inside_count > max_onions_reg) max_onions_reg <= inside_count;\n                    state <= NEXT_S;\n                end\n\n                NEXT_S: begin\n                    if (s < 3'd4) begin\n                        s <= s + 3'd1;\n                        state <= GET_FENCE_VERTICES;\n                    end else begin\n                        state <= DONE;\n                    end\n                end\n\n                DONE: begin\n                    max_onions <= max_onions_reg;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule